99:           method,
100:           path,
101:           from,
102:           request,
103:           targetServer: stage === 1 ? serverAddress : null,
104:           cacheStatus: null,
105:           dbOp: null,
106:           dbStale: false,
107:           response: null,
108:           status: null,
