1: // DOCUMENTS: a round-robin load balancer at a public mini-IP (default 10.1).
2: // Holds an ordered list of backend server mini-IPs (e.g. ['10.11', '10.12'])
3: // and a cursor `nextIndex`. Each incoming request selects
4: // `backends[nextIndex]`, advances `nextIndex = (nextIndex + 1) % backends.length`,
5: // and forwards the request across the network to that backend's queue or
6: // synchronous handler.
7: //
8: // CHECKS: constructor rejects an invalid mini-IP address or an empty /
9: // malformed backend pool so misconfigured topologies fail loud at boot.
10: const MINI_IP = /^\d+\.\d+$/;
11: 
12: export function createLoadBalancer({
13:   address = '10.1',
14:   backends = ['10.11', '10.12'],
15:   network = null,
16: } = {}) {
17:   if (!MINI_IP.test(address)) {
18:     throw new Error(`loadbalancer: invalid mini-IP address ${address}`);
19:   }
20:   if (
21:     !Array.isArray(backends) ||
22:     backends.length === 0 ||
23:     !backends.every((b) => MINI_IP.test(b))
24:   ) {
25:     throw new Error('loadbalancer: backends must be a non-empty list of <net>.<host> addresses');
26:   }
27:   const pool = [...backends];
28:   const perBackend = Object.fromEntries(pool.map((b) => [b, 0]));
29:   let nextIndex = 0;
30:   let forwarded = 0;
31:   let lastTarget = null;
32: 
33:   function selectBackend() {
34:     const target = pool[nextIndex];
35:     nextIndex = (nextIndex + 1) % pool.length;
36:     forwarded += 1;
37:     perBackend[target] += 1;
38:     lastTarget = target;
39:     return target;
40:   }
41: 
42:   return {
43:     get address() {
44:       return address;
45:     },
46: 
47:     get backends() {
48:       return [...pool];
49:     },
50: 
51:     nextBackend() {
52:       return pool[nextIndex];
53:     },
54: 
55:     selectBackend,
56: 
57:     handleRequest(request = 'GET /') {
58:       if (!network) throw new Error('loadbalancer: no network attached');
59:       const target = selectBackend();
60:       return network.send({ from: address, to: target, request }).response;
61:     },
62: 
63:     enqueue({ id, atTick, from = '10.2', request = 'GET /', isYou = false }) {
64:       if (!network) throw new Error('loadbalancer: no network attached');
65:       const target = selectBackend();
66:       network.deliverToQueue({ id, from, to: target, request, atTick, isYou });
67:       return target;
68:     },
69: 
70:     snapshot() {
71:       return {
72:         address,
73:         algorithm: 'round-robin',
74:         backends: [...pool],
75:         nextBackend: pool[nextIndex],
76:         forwarded,
77:         lastTarget,
78:         perBackend: { ...perBackend },
79:       };
80:     },
81:   };
82: }

