// DOCUMENTS: the Stage 6 component — a resolver with an authoritative
// table and a tick-TTL answer ledger (the cache.js pattern applied to
// names). lookup(name, currentTick) answers a live ledger entry straight
// from the ledger (cachedHits), consults the authoritative table only on
// a miss or an expired entry, and reports unknown names as NX without
// throwing — the fail-loud throw rule lives at the network layer, not here.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer.
export function createDns({ address = '10.60', ttlTicks = 300, records = { 'example.com': '10.1' } } = {}) {
  if (!/^\d+\.\d+$/.test(address)) throw new Error(`dns: invalid mini-IP address ${address}`);
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  const entries = new Map();
  let lookups = 0, cachedHits = 0, authoritative = 0, lastLookup = null;
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = entries.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', name, target: entry.target, source: 'ledger' };
    }
    if (entry) entries.delete(name);
    authoritative += 1;
    const target = Object.prototype.hasOwnProperty.call(records, name) ? records[name] : null;
    if (target) {
      entries.set(name, { name, target, cachedAtTick: currentTick, expiresAtTick: currentTick + ttlTicks });
      lastLookup = { name, status: 'MISS', target, atTick: currentTick };
      return { status: 'OK', name, target, source: 'authoritative' };
    }
    lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
    return { status: 'NX', name };
  }
  function snapshot(currentTick = 0) {
    for (const [key, entry] of entries) if (currentTick >= entry.expiresAtTick) entries.delete(key);
    return { address, ttlTicks, lookups, cachedHits, authoritative, lastLookup,
      cache: [...entries.values()].map((e) => ({ name: e.name, target: e.target, cachedAtTick: e.cachedAtTick, expiresAtTick: e.expiresAtTick, ttlRemaining: e.expiresAtTick - currentTick })) };
  }
  return { get address() { return address; }, lookup, snapshot };
}
```

