// DOCUMENTS: the Stage 6 component — a resolver with a small authoritative
// table and a tick-TTL answer ledger (cache.js's ledger pattern applied to
// names). lookup(name, currentTick) answers a live ledger entry straight
// from the ledger (cachedHits) with no authoritative consult; a miss or an
// expired entry consults the authoritative table and fills the ledger;
// unknown names answer NX at the DNS layer without throwing — the fail-loud
// throw rule lives at the network layer for addresses, not names here.
// Deterministic by construction: no clock, no RNG — time arrives as the
// `currentTick` argument, the same way the WebServer keeps time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration, mirroring cache.js).
export function createDns({
  address = '10.60',
  ttlTicks = 300,
  records = { 'example.com': '10.1' },
} = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const entries = new Map(); // name -> { name, target, cachedAtTick, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let lastLookup = null;

  // An entry is stale the moment the current tick reaches its expiry:
  // filled at tick T with ttlTicks = 300 means alive through tick T + 299.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = entries.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', name, target: entry.target, source: 'ledger' };
    }
    // An expired entry is dropped here, before the authoritative consult —
    // it can never answer from the ledger past its own expiry tick.
    if (entry) entries.delete(name);
    authoritative += 1;
    const target = Object.prototype.hasOwnProperty.call(records, name)
      ? records[name]
      : null;
    if (target) {
      entries.set(name, {
        name,
        target,
        cachedAtTick: currentTick,
        expiresAtTick: currentTick + ttlTicks,
      });
      lastLookup = { name, status: 'MISS', target, atTick: currentTick };
      return { status: 'OK', name, target, source: 'authoritative' };
    }
    lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
    return { status: 'NX', name };
  }

  function snapshot(currentTick = 0) {
    for (const [name, entry] of entries) {
      if (currentTick >= entry.expiresAtTick) entries.delete(name);
    }
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      lastLookup,
      cache: [...entries.values()].map((e) => ({
        name: e.name,
        target: e.target,
        cachedAtTick: e.cachedAtTick,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 cross-subnet Router — a two-interface component
// joining the 10.x and 20.x network instances. A frame whose destination
// lives outside its ingress network's subnet takes exactly one router hop
// (routed +1) and is delivered on the peer network; unknown hosts on the
// peer side fail loud there ("no server at 20.9" — DL-1, mirroring
// network.js). Frames addressed to the router's own interfaces answer a
// slim "200 router": the interfaces are reachable, nothing sits behind
// them until Stage 6b occupies the 20-side with the CDN edge.
//
// CHECKS: both interface addresses must be two-number mini-IPs on distinct
// subnets, and routing before join() fails loud.
const MINI_IP = /^\d+\.\d+$/;

const subnetOf = (address) => String(address).split('.')[0];

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  if (subnetOf(leftAddress) === subnetOf(rightAddress)) {
    throw new Error(
      `router: interfaces must join two subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let left = null;
  let right = null;
  let routed = 0;
  let lastFrame = null;

  function join({ left: leftNetwork, right: rightNetwork }) {
    if (!leftNetwork || !rightNetwork) {
      throw new Error('router: join needs both network instances');
    }
    left = leftNetwork;
    right = rightNetwork;
  }

  function peerOf(ingress) {
    if (!left || !right) throw new Error('router: no networks joined');
    return ingress === 'left' ? right : left;
  }

  // One hop: count it, name it on the wire, hand the frame to the peer
  // network for local delivery. The frame crosses the router exactly once —
  // the peer delivery path (deliverRouted) carries no router of its own.
  function route({ from, to, request, side: ingress }) {
    const peer = peerOf(ingress);
    routed += 1;
    lastFrame = `${from} -> ${to} routed via ${leftAddress} ⇄ ${rightAddress}`;
    return peer.deliverRouted({ from, to, request });
  }

  function routeQueue({ id, from, to, request, atTick, isYou = false, side: ingress }) {
    const peer = peerOf(ingress);
    routed += 1;
    lastFrame = `${from} -> ${to} routed via ${leftAddress} ⇄ ${rightAddress}`;
    peer.deliverRoutedQueue({ id, from, to, request, atTick, isYou });
  }

  // The router doubles as a reachable server on each of its interfaces, so
  // a frame sent to 20.1 (or 10.65) itself answers instead of throwing.
  function handleRequest() {
    return '200 router';
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    join,
    route,
    routeQueue,
    handleRequest,
    snapshot() {
      return { leftAddress, rightAddress, routed, lastFrame };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 attaches a
// cross-subnet Router: a frame addressed outside this network's own subnet
// takes exactly one router hop to the peer network, and unregistered hosts
// fail loud both before the router (same-subnet) and after it (peer side).
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud.
const MINI_IP = /^\d+\.\d+$/;

const subnetOf = (address) => String(address).split('.')[0];

export function createNetwork({ subnet = null } = {}) {
  const servers = new Map();
  let crossRouter = null; // { router, side } — set by attachRouter (Stage 6)

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // CHECKS: a router hop fires only when the destination lives outside this
  // network's own subnet — same-subnet unknown hosts keep the plain
  // "no server at" failure with no routed counter movement.
  function crossTarget(to) {
    if (crossRouter && subnet !== null && subnetOf(to) !== subnet) {
      return crossRouter;
    }
    return null;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    attachRouter(router, side) {
      crossRouter = { router, side };
    },

    resolve,

    send({ from, to, request }) {
      validate(from);
      validate(to);
      const server = servers.get(to);
      if (server) {
        return { from, to, request, response: server.handleRequest(request) };
      }
      const crossing = crossTarget(to);
      if (crossing) {
        return crossing.router.route({ from, to, request, side: crossing.side });
      }
      throw new Error(`network: no server at ${to}`);
    },

    // Local delivery for a frame that already took its one router hop on
    // the ingress side: unknown hosts here fail loud with the same
    // "no server at" error shape the subnet's own sends have always had.
    deliverRouted({ from, to, request }) {
      validate(from);
      validate(to);
      return { from, to, request, response: resolve(to).handleRequest(request) };
    },

    deliverRoutedQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      resolve(to).enqueue({ id, from, to, request, atTick, isYou });
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      const server = servers.get(to);
      if (server) {
        server.enqueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const crossing = crossTarget(to);
      if (crossing) {
        crossing.router.routeQueue({
          id,
          from,
          to,
          request,
          atTick,
          isYou,
          side: crossing.side,
        });
        return;
      }
      throw new Error(`network: no server at ${to}`);
    },
  };
}

