parseResponse(raw) {
  const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
  return { status: Number(statusToken), body: bodyParts.join(' ') };
},

input.newString:
parseResponse(raw) {
  const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
  const numeric = Number(statusToken);
  // Stage 6: a DNS answer carries a non-numeric status token ("NX no
  // record ..."); the browser renders it as-is instead of a NaN badge.
  return { status: Number.isNaN(numeric) ? statusToken : numeric, body: bodyParts.join(' ') };
},

