// DOCUMENTS: the Stage 6 DNS segment of the hop-by-hop trace machine — the
// three hosted-path hops before the Stage 5 chain takes over (emit, ask,
// answer) and the NX dead-end that ends a trace with no GET on the wire.
// Split from trace.js by responsibility (guard-file-size): the segment owns
// no state of its own — it mutates the trace record the machine hands in
// and consults the real DNS component's lookup() ledger.
//
// CHECKS: the host/path split fires only on a path that carries a host
// ("<host>/<path>", first-slash grammar); a plain "/<path>" stays host-less
// and the machine keeps the Stage 5 story hop for hop.

// Returns { host, suffix } for a hosted path ("example.com/about"), or null
// when the path is host-less ("/about") and no DNS hop may be inserted.
export function splitHostPath(path = '') {
  const raw = String(path);
  if (raw.startsWith('/')) return null;
  const slashAt = raw.indexOf('/');
  if (slashAt === -1) return { host: raw, suffix: '/' };
  return { host: raw.slice(0, slashAt), suffix: raw.slice(slashAt) };
}

// Hop 2: the browser asks DNS; the ledger lookup runs here, so the counters
// move once per hosted trace. An unknown name pins the trace to the 3-hop
// NX dead-end (ask + answer, nothing else).
export function stepDnsAsk(trace, { dns, getTick }) {
  const answer = dns.lookup(trace.dns.host, getTick());
  trace.dns.status = answer.status;
  trace.dns.target = answer.target ?? null;
  if (answer.status === 'NX') trace.totalHops = 3;
  return `${trace.from} -> ${dns.address} | ${trace.dns.host} ?`;
}

// Hop 3: the DNS answer rides back to the browser. A hit names the ledger
// state ("cache HIT") versus the authoritative consult; an NX answer is
// delivered to the browser as the rendered record — no GET follows it.
export function stepDnsAnswer(trace, { dns, onFinish }) {
  if (trace.dns.status === 'NX') {
    const response = `NX no record for ${trace.dns.host}`;
    onFinish({
      from: trace.from,
      to: dns.address,
      request: trace.request,
      response,
    });
    return `${dns.address} -> ${trace.from} | ${response}`;
  }
  const how = trace.dns.status === 'HIT' ? 'cache HIT' : 'authoritative';
  return `${dns.address} -> ${trace.from} | ${trace.dns.host} = ${trace.dns.target} (${how})`;
}

// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
// backend's cache-aside lookup and the HTTP response emission split into
// two hops so the learner can watch Cache 10.20 answer, then the backend
// emit); 7 in Stage 4 (the Database hop inserted after the cache check —
// the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
// 10.31, or the SKIP a warm cache HIT earns); 8 in Stage 5 (the async
// WorkerQueue hops). Stage 6 branches on the path itself: a hosted path
// ("example.com/about") spends two DNS hops at 10.60 (ask, answer) before
// the Stage 5 chain continues — 10 hops total — while a host-less path
// ("/about") keeps the Stage 5 8-hop story untouched, and an unknown name
// dead-ends at hop 3 with the NX answer and no GET on the wire (the
// segment lives in trace-dns.js).
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance.
import { splitHostPath, stepDnsAsk, stepDnsAnswer } from './trace-dns.js';

const FINAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 10 };

export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  let trace = freshTrace();
  let served = null; // the drained response record, held between hops 4/6 and 5/6

  function freshTrace() {
    return {
      hop: 0,
      method: 'GET',
      path: '/about',
      from: '10.2',
      request: 'GET /about',
      kind: 'plain',
      totalHops: FINAL_HOPS[stage],
      dns: null,
      splitRequest: null,
      targetServer: null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
  }

  // The request the wire actually carries: a hosted Stage 6 trace emits the
  // full URL at hop 1 but sends the host-stripped GET down the chain.
  const wireRequest = () => trace.splitRequest ?? trace.request;

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: wireRequest(),
      response: trace.response,
    });
  }

  // The WRITE / SELECT / SKIP frame text shared by the Stage 4 and Stage 5
  // database hops — one builder so both stages narrate identically.
  function dbOpFrame() {
    if (trace.dbOp === 'WRITE') {
      return `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
    }
    if (trace.dbOp === 'SELECT') {
      return `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
    }
    return `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      let frame = null;
      if (trace.hop === 0 || trace.hop >= trace.totalHops) {
        const split = stage >= 6 ? splitHostPath(path) : null;
        const request = `${method} ${path}`;
        trace = {
          hop: 1,
          method,
          path,
          from,
          request,
          kind: split ? 'hosted' : 'plain',
          totalHops: stage >= 6 ? (split ? 10 : 8) : FINAL_HOPS[stage],
          dns: split ? { host: split.host, path: split.suffix, status: null, target: null } : null,
          splitRequest: split ? `${method} ${split.suffix}` : null,
          targetServer: stage === 1 ? serverAddress : null,
          cacheStatus: null,
          dbOp: null,
          dbStale: false,
          response: null,
          status: null,
          body: null,
          routeId: null,
        };
        served = null;
        frame =
          stage >= 6 && split
            ? `${from} -> ${dns.address} | ${request}`
            : `${from} -> ${serverAddress} | ${request}`;
        return frame;
      }
      // Stage 6 hosted path: hops 1-3 belong to the DNS segment (emit,
      // ask, answer); the Stage 5 chain then runs from hop 4.
      if (stage >= 6 && trace.kind !== 'plain' && trace.hop === 1) {
        trace.hop = 2;
        return stepDnsAsk(trace, { dns, getTick });
      }
      if (stage >= 6 && trace.kind !== 'plain' && trace.hop === 2) {
        trace.hop = 3;
        return stepDnsAnswer(trace, { dns, onFinish });
      }
      // The shared per-stage chain: Stage 6 reuses the Stage 5 chain two
      // hops in (hosted) or verbatim (host-less) — the branch conditions
      // key on (chainStage, chainHop) so every stage narrates from one body
      // of hop logic.
      const chainStage = stage >= 6 ? 5 : stage;
      const chainHop = trace.hop - (stage >= 6 && trace.kind !== 'plain' ? 2 : 0);
      if (chainStage === 1 && chainHop === 1) {
        trace.hop += 1;
        const atTick = bumpTick();
        network.deliverToQueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: wireRequest(),
          atTick,
          isYou: true,
        });
        frame = `routed ${trace.from} -> ${serverAddress} (${wireRequest()}) into queue`;
      } else if (chainStage === 1 && chainHop === 2) {
        trace.hop += 1;
        const you = drainUntilYou(servers[0]);
        if (you) {
          serve(you);
          frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
        }
      } else if (chainStage === 1 && chainHop === 3) {
        trace.hop += 1;
        finish(serverAddress);
      } else if (chainHop === 1) {
        trace.hop += 1;
        frame = `routed ${trace.from} -> ${serverAddress} (${wireRequest()}) to LoadBalancer`;
      } else if (chainHop === 2) {
        trace.hop += 1;
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: wireRequest(),
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${wireRequest()}) queued`;
      } else if (chainStage === 2 && chainHop === 3) {
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        const you = drainUntilYou(backend);
        if (you) {
          serve(you);
          frame = `${backend.address} -> ${trace.from} | ${you.response}`;
        }
      } else if (chainStage === 2 && chainHop === 4) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (chainStage === 3 && chainHop === 3) {
        // Hop 4/6: the target backend checks Cache and serves the queued
        // request; the response record is held one hop so the learner sees
        // the cache lookup before the response leaves the backend.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (chainStage === 3 && chainHop === 4) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
        }
      } else if (chainStage === 3 && chainHop === 5) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (chainStage === 4 && chainHop === 3) {
        // Hop 4/7: the target backend checks Cache and serves the queued
        // request (a POST write-through carries cacheStatus INVALIDATE);
        // the response record is held so the learner watches the cache
        // lookup, then the database hop.
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.path})`;
        }
      } else if (chainStage === 4 && chainHop === 4) {
        // Hop 5/7: the database hop — hop 6's WRITE landed on Primary
        // 10.30 (replication queued toward 10.31), hop 5's SELECT read
        // Replica 10.31 fresh or stale, and a warm cache HIT skips the
        // database entirely.
        trace.hop += 1;
        if (served) {
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          frame = dbOpFrame();
        }
      } else if (chainStage === 4 && chainHop === 5) {
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (chainStage === 4 && chainHop === 6) {
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
      } else if (chainStage === 5 && chainHop === 3) {
        // Hop 4/8: an async POST /jobs enqueues to WorkerQueue 10.40; other
        // requests narrate the cache/database hop they actually took (the
        // Stage 4 story) — no phantom async jobs on GET traces (DL-4).
        trace.hop += 1;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
            frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.path})`;
          } else {
            frame = dbOpFrame();
          }
        }
      } else if (chainStage === 5 && chainHop === 4) {
        // Hop 5/8: the webserver answers — an immediate 202 for async jobs,
        // the actually-served response for everything else.
        trace.hop += 1;
        if (served) {
          serve(served);
          frame = served.asyncJob
            ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
            : `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (chainStage === 5 && chainHop === 5) {
        // Hop 6/8: WebServer returns its response via Network
        trace.hop += 1;
        frame = `Network delivered ${trace.status} response to ${trace.from}`;
      } else if (chainStage === 5 && chainHop === 6) {
        // Hop 7/8: Browser receives and displays the response
        trace.hop += 1;
        finish(trace.targetServer ?? serverAddress);
        frame = `Browser ${trace.from} received and displayed ${trace.status}`;
      } else if (chainStage === 5 && chainHop === 7) {
        // Hop 8/8: async job tails with the worker's commit; a request that
        // was served synchronously finds the worker idle.
        trace.hop += 1;
        const dbTarget = database ? database.primaryAddress : '10.30';
        const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
        frame = trace.asyncJob
          ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
          : `Worker ${workerAddr} idle — no async jobs in this trace`;
      }
      return frame;
    },

    snapshot() {
      return { ...trace, done: trace.hop >= trace.totalHops };
    },
  };
}

