export const TICK_MS = 100;
const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
// Total hops per stage's trace shape (trace.js and engine.traceHop agree).
// Stage 6's pinned maximum is the hosted path: the stage-5 8-hop chain plus
// two DNS hops. A host-less stage-6 trace stays at 8, an NX dead-end at 3 —
// the live trace record carries its own totalHops.
const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 10 };

const HOP_START_SENTENCE = 'Idle — type a path and click Go or Step 1 Hop ->';

function fillPercent(depth) {
  return `${Math.min(100, Math.round((depth / QUEUE_BAR_SATURATION) * 100))}%`;
}

// Stage 5's eight hop texts without their "Hop N/8" prefix. Stage 5 renders
// them verbatim and the stage-6 narratives reuse the same bodies, so a
// host-less stage-6 trace reads byte-identical to stage 5 (named
// counter-example pinned in test/panel/model-stage6.test.js).
function stage5Bodies(t, snapshot, from, serverAddress) {
  const target = t.targetServer ?? '10.11';
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  if (t.asyncJob) {
    return [
      `Browser (${from}) emits "${t.request}"`,
      `Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `LoadBalancer (${serverAddress}) -> ${target} queue`,
      `WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `WebServer (${target}) -> "202 Accepted"`,
      `Network delivers 202 response to ${from}`,
      `Browser (${from}) received and displayed 202 Accepted`,
      `Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  const dbOp =
    t.dbOp === 'WRITE'
      ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
      : t.dbOp === 'SELECT' && t.dbStale
        ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
        : t.dbOp === 'SELECT'
          ? `Database SELECT @ Replica (${replica}) — fresh`
          : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
  return [
    `Browser (${from}) emits "${t.request}"`,
    `Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `LoadBalancer (${serverAddress}) -> ${target} queue`,
    dbOp,
    `WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Network delivers ${t.status} response to ${from}`,
    `Browser (${from}) received and displayed ${t.status}`,
    `Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

const withHopPrefix = (bodies, total) =>
  bodies.map((body, i) => `Hop ${i + 1}/${total}: ${body}`);

// One hop-status sentence per hop, in hop order, for each stage's trace
// shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check), 8 in Stage 5. Stage 6
// branches on the trace's path kind: a hosted path ("example.com/about")
// adds the DNS ask + answer ahead of the stage-5 bodies (10 hops), a
// host-less path ("/about") reuses stage 5 verbatim, and an unknown name
// dead-ends at hop 3 with the NX answer.
function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  if (stage === 6) {
    const dnsAddress = snapshot.dns?.address ?? '10.60';
    if (t.dns && t.dns.status === 'NX') {
      const host = t.dns.host;
      return [
        `Hop 1/3: Browser (${from}) emits "${t.request}"`,
        `Hop 2/3: Browser (${from}) asks DNS (${dnsAddress}) — ${host} = ?`,
        `Hop 3/3: DNS (${dnsAddress}) answers NX no record for ${host}`,
      ];
    }
    if (t.dns) {
      const total = t.totalHops ?? 10;
      const bodies = stage5Bodies(t, snapshot, from, serverAddress);
      return withHopPrefix(
        [
          bodies[0],
          `Browser (${from}) asks DNS (${dnsAddress}) — ${t.dns.host} = ?`,
          `DNS (${dnsAddress}) answers ${t.dns.host} = ${t.dns.target} (${
            t.dns.status === 'HIT' ? 'cache HIT' : 'authoritative'
          })`,
          ...bodies.slice(1),
        ],
        total,
      );
    }
    // Host-less: the stage-5 story, denominators and all.
    return withHopPrefix(stage5Bodies(t, snapshot, from, serverAddress), 8);
  }
  if (stage === 5) {
    return withHopPrefix(stage5Bodies(t, snapshot, from, serverAddress), 8);
  }

