// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing; Stage 6
// opens with the DNS ask/answer on hosted paths (node-dns lights up),
// then reuses the Stage 5 map two hops in — host-less traces and NX
// dead-ends follow their own shapes.
function stage5Target(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.trace?.asyncJob) {
    // Async POST /jobs walks browser -> lb -> enqueue -> 202 -> worker
    // commit; every other request keeps the Stage 4 cache/db story and the
    // worker reads idle on the tail hop.
    const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
    const owners = {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: 'node-queue',
      5: 'node-webserver',
      6: 'node-network',
      7: 'node-browser',
      8: 'node-worker',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: 'packet-req-queue',
      5: 'packet-res-cache',
      6: 'packet-res-right',
      7: 'packet-res-left',
      8: 'packet-res-db',
    };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  const backendCard =
    snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  const owners = {
    1: 'node-browser',
    2: 'node-network',
    3: 'node-lb',
    4: 'node-db',
    5: backendCard,
    6: 'node-network',
    7: 'node-browser',
    8: 'node-worker',
  };
  const lanes = {
    1: 'packet-req-left',
    2: 'packet-req-right',
    3: 'packet-req-lb',
    4: dbLane,
    5: 'packet-res-cache',
    6: 'packet-res-right',
    7: 'packet-res-left',
    8: 'packet-res-worker',
  };
  return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
}

function activeHopTarget(snapshot) {
  if (snapshot.stage === 6) {
    const hop = snapshot.trace?.hop ?? 0;
    const t = snapshot.trace ?? {};
    if (t.dns) {
      // Hosted / NX paths: hops 1-3 are the DNS segment. Hop 1 is the
      // browser's emit; the ask and the answer execute on node-dns. The
      // wire lane chips have no DNS lane, so the browser↔network lane
      // carries the segment visually.
      if (hop <= 3) {
        const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-dns' };
        return { cardId: owners[hop] ?? 'node-browser', laneId: 'packet-req-left' };
      }
      // Hops 4-10 are the Stage 5 chain two hops in.
      return stage5Target({ ...snapshot, trace: { ...t, hop: hop - 2 } });
    }
    // Host-less: the stage-5 story verbatim.
    return stage5Target(snapshot);
  }
  if (snapshot.stage === 5) {
    return stage5Target(snapshot);
  }
  if (snapshot.stage === 4) {
    const backendCard =
      snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';

