function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  // The live trace carries its own hop total — a hosted stage-6 run reads
  // "hop N/10" while its host-less neighbour keeps "hop N/8".
  const totalHops = snapshot.trace.totalHops ?? totalHopsFor(snapshot.stage);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  const finalHop = totalHopsFor(currentStage);
  const iv = setInterval(() => {
    const trace = stepOneHop().trace;
    // A trace ends at its own hop total, which an NX dead-end reaches at
    // hop 3 — well before the hosted stage-6 maximum.
    if (trace.hop === finalHop || trace.done) clearInterval(iv);
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  const finalHop = totalHopsFor(currentStage);
  for (let i = 0; i < finalHop + 1; i += 1) {
    const trace = stepOneHop().trace;
    if (trace.hop === finalHop || trace.done) break;
  }
});

